    const m = { schemaVersion: 1, id: STORY, version: '2.0.0', type: 'story', minAppVersion: '1.0.0', totalBytes: files.reduce((a, f) => a + f.bytes, 0), files, metadata: { storyId: STORY, title: 'D', language: 'pt-BR' } };
