        try { const { rA } = await comJoin(svc, h, 'david_goliath', 'delete', () => Promise.reject(new Error('r')), () => {}); await new Promise((r) => setTimeout(r, 30)); sig = `unhandled=${rej.length}|okA=${rA && rA.ok}`; }
