          if (changed) { if (prev && typeof prev.cleanup === 'function') prev.cleanup(); const rec = { __eff: true, deps: p.deps, cleanup: undefined }; slots[p.i] = rec; const c = p.effect(); rec.cleanup = typeof c === 'function' ? c : undefined; }
