    check('LP2.1 G1-D/7 (um ready por publicação física, com 3 chamadas): C não gera um terceiro evento global',
      D.readys.length === 2 && D.readys[0] === '2.0.0' && D.readys[1] === '3.0.0', JSON.stringify(D.readys));

