    const REG = novoRegG5(mutReg);
    const readys = [];
    const pararReadys = REG.subscribePackReady((s) => readys.push((s && s.version) || null));
    const svc = novoSvcG5(mutSvc)({ ...h.deps, installRegistry: REG, clearPackEntry: h.storage.clearPackEntry });

